insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La carta d''identità hardware', 'Descrivi il tuo PC o il tuo telefono come un tecnico: processore, RAM, archiviazione dichiarata e mostrata (con il conto tra potenze di 1000 e di 1024) e almeno 6 periferiche classificate. Ridisegna il dispositivo con lo schema di von Neumann. Consegna il file hardware-cognome.pdf.', null, '2026-10-30', (select id from topics where class_id = '3g' and title = 'I sistemi di elaborazione' limit 1), 'contenuti/compiti/sistemi-di-elaborazione.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La carta d''identità hardware');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'L''inventario del software', 'Elenca 12 software di un tuo dispositivo, indicando tipo (base, utility, applicativo) e licenza con la fonte. Su OnlineGDB scrivi un piccolo programma Java, provoca due errori di compilazione e uno di esecuzione e spiega i messaggi. Consegna il file software-cognome.pdf.', null, '2026-11-03', (select id from topics where class_id = '3g' and title = 'Il software' limit 1), 'contenuti/compiti/software-e-linguaggi.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'L''inventario del software');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il pianeta delle basi', 'Converti numeri tra le basi 3, 5, 8 e 10, esegui somme binarie in colonna, rispondi a domande sui trucchi e inventa un popolo alieno con la sua base. Verifica tutto nella console del browser e correggi gli errori. Consegna il file basi-cognome.pdf.', null, '2026-11-06', (select id from topics where class_id = '3g' and title = 'I sistemi di numerazione' limit 1), 'contenuti/compiti/basi-di-numerazione.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il pianeta delle basi');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Caccia all''esadecimale', 'Trova e decodifica l''ottale e l''esadecimale nei tuoi dispositivi: il MAC del telefono o del PC, un colore di un sito, le firme di tre file con HexEd.it, alcuni permessi Unix e due conversioni tra ottale ed esadecimale. Consegna il file caccia-hex-cognome.pdf.', null, '2026-11-10', (select id from topics where class_id = '3g' and title = 'Altri sistemi di numerazione' limit 1), 'contenuti/compiti/ottale-ed-esadecimale.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Caccia all''esadecimale');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il convertitore universale', 'Scrivi in Java un programma che converte un numero da qualsiasi base tra 2 e 16 a qualsiasi altra, con lo schema di Horner e le divisioni successive, gestendo cifre e basi non valide. Aggiungi in un commento una tabella di almeno 6 test con i casi limite. Consegna il file convertitore-cognome.java.', null, '2026-11-12', (select id from topics where class_id = '3g' and title = 'Laboratorio: la codifica dei numeri' limit 1), 'contenuti/compiti/laboratorio-codifica-numeri.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il convertitore universale');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il termometro della base polare', 'Converti a mano numeri negativi in complemento a 2 su 8 bit, calcola tre somme in binario riconoscendo l''overflow e costruisci in Calc un foglio che trasforma le temperature di una settimana in Antartide in byte e li rilegge con i pesi. Consegna il file termometro-c2-cognome.ods con i fogli Esercizi e Termometro.', null, '2026-11-17', (select id from topics where class_id = '3g' and title = 'Rappresentazione dei numeri interi relativi' limit 1), 'contenuti/compiti/numeri-interi-relativi.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il termometro della base polare');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Caccia all''arrotondamento', 'Converti a mano numeri con la virgola in binario e due numeri in float IEEE 754, verificandoli con il FloatConverter; poi confronta in Java un totale calcolato con i double e con i centesimi interi e spiega al titolare di un negozio online quale versione usare. Consegna il file virgola-mobile-cognome.pdf.', null, '2026-11-19', (select id from topics where class_id = '3g' and title = 'Rappresentazione dei numeri reali' limit 1), 'contenuti/compiti/numeri-reali-virgola-mobile.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Caccia all''arrotondamento');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Caccia ai tre bug', 'Un programma Java che calcola la media dei voti e i millisecondi in un anno contiene tre bug: trovali con il debugger di OnlineGDB, correggili e spiega ognuno con un commento nel codice (che cosa vedevi, la causa, la correzione). Consegna il file bug-cognome.java.', null, '2026-11-23', (select id from topics where class_id = '3g' and title = 'Laboratorio: il debugger e le variabili' limit 1), 'contenuti/compiti/debugger-variabili-java.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Caccia ai tre bug');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il messaggio in byte', 'Decodifica a mano un messaggio scritto in byte UTF-8 esadecimali, contando caratteri e byte, poi codifica una tua risposta con una lettera accentata, il simbolo dell''euro e un''emoji e verificala con HexEd.it o con la console. Consegna il file utf8-cognome.pdf.', null, '2026-11-26', (select id from topics where class_id = '3g' and title = 'Codifica dei dati alfanumerici' limit 1), 'contenuti/compiti/codifica-caratteri.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il messaggio in byte');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Detective dei pixel', 'Analizza tre foto molto diverse fatte con il telefono: risoluzione, megapixel, peso non compresso a 24 bit, peso reale e rapporto di compressione, con le formule in Calc. Disegna una riga di 20 pixel, codificala in RLE e spiega quale foto si comprime di più e perché. Consegna il file pixel-cognome.ods.', null, '2026-11-30', (select id from topics where class_id = '3g' and title = 'Le immagini raster' limit 1), 'contenuti/compiti/immagini-raster.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Detective dei pixel');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Una foto, sei file', 'Trasforma una tua foto in sei versioni con Squoosh (JPEG a tre qualità, WebP, AVIF, PNG) e confrontale in Calc per peso, qualità visiva e firma esadecimale letta con HexEd.it. Controlla i metadati della foto originale e scegli la versione migliore per sito, stampa e chat. Consegna il file formati-cognome.ods.', null, '2026-12-02', (select id from topics where class_id = '3g' and title = 'Laboratorio: i file immagine' limit 1), 'contenuti/compiti/laboratorio-file-immagine.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Una foto, sei file');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il mio stemma in SVG', 'Progetta su carta e scrivi a mano un file SVG 300 × 300 con almeno due forme, un poligono, un tracciato con una curva, un testo, title, desc e commenti. Rasterizzalo in Photopea e confronta in un commento finale il peso dell''SVG, del PNG e del PNG non compresso. Consegna il file stemma-cognome.svg.', null, '2026-12-07', (select id from topics where class_id = '3g' and title = 'Le immagini vettoriali' limit 1), 'contenuti/compiti/immagini-vettoriali.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il mio stemma in SVG');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Stop motion da scrivania', 'Scatta almeno 12 fotogrammi con il telefono e crea un''animazione GIF con ezgif scegliendo il delay. In Calc calcola fps, durata, peso non compresso e rapporto di compressione, e spiega perché la GIF ha colori a chiazze e quale formato video sarebbe migliore. Consegna il file stopmotion-cognome.zip con la GIF e il foglio di calcolo.', null, '2026-12-10', (select id from topics where class_id = '3g' and title = 'Le immagini in movimento' limit 1), 'contenuti/compiti/immagini-in-movimento.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Stop motion da scrivania');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Quante canzoni in un giga?', 'Misura formato, durata e peso di una tua nota vocale e calcolane il bitrate e il peso in WAV qualità CD. In Calc calcola il peso di una canzone con quattro qualità e quante ne stanno in 1 GB, scegli la qualità per dati mobili e Wi-Fi e rispondi a due domande sul campionamento. Consegna il file audio-cognome.ods.', null, '2026-12-14', (select id from topics where class_id = '3g' and title = 'I suoni' limit 1), 'contenuti/compiti/suono-digitale.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Quante canzoni in un giga?');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La multimedialità in 60 secondi', 'Registra e monta con AudioMass una mini-puntata di podcast di 45-75 secondi che spiega un argomento dell''Unità 2 con un calcolo vero: tagli, fade e normalizzazione. Esporta in WAV e MP3, confronta i pesi reali e calcolati e leggi l''intestazione del WAV con HexEd.it. Consegna il file podcast-cognome.zip con podcast.mp3 e scheda.txt.', null, '2026-12-17', (select id from topics where class_id = '3g' and title = 'Laboratorio: i file audio' limit 1), 'contenuti/compiti/laboratorio-file-audio.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La multimedialità in 60 secondi');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il mio classificatore onesto', 'Addestra con Teachable Machine un modello che riconosce tre oggetti di casa, provalo con 10 immagini nuove per oggetto e costruisci in Calc la matrice di confusione con l''accuratezza. Ripeti con una versione addestrata male di proposito e rifletti su bias e privacy. Consegna il file classificatore-cognome.ods.', null, '2026-12-21', (select id from topics where class_id = '3g' and title = 'Intelligenza artificiale e computer vision' limit 1), 'contenuti/compiti/computer-vision.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il mio classificatore onesto');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Autopsia di un bug famoso', 'Scegli un guasto software realmente accaduto (Ariane 5, Mars Climate Orbiter, Patriot, Therac-25, Y2K, CrowdStrike 2024) e ricostruiscilo con almeno due fonti: che cosa è successo, la causa tecnica con un esempio, la caratteristica di qualità mancata e due contromisure. Chiudi con una riflessione sugli assistenti di AI. Consegna il file bug-famoso-cognome.pdf.', null, '2027-01-07', (select id from topics where class_id = '3g' and title = 'Ingegneria del software' limit 1), 'contenuti/compiti/ingegneria-del-software.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Autopsia di un bug famoso');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Test a prova di bomba', 'Partendo dal requisito del prezzo del biglietto di un museo, scrivi prima almeno 12 casi di test con tutti i valori al limite, poi il metodo Java prezzo(eta) e un metodo prova che stampa OK o ERRORE, finché tutti i test passano. Consegna il file Biglietto.java con la tabella dei casi in un commento.', null, '2027-01-12', (select id from topics where class_id = '3g' and title = 'Il ciclo di vita del software' limit 1), 'contenuti/compiti/modelli-ciclo-di-vita.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Test a prova di bomba');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La mia settimana in Kanban', 'Per una settimana gestisci studio e impegni con una board Kanban personale (Da fare, In corso con limite 2, Fatto) con almeno 10 attività stimate in punti. Ogni sera scrivi un breve Daily e alla fine una retrospettiva con una regola per migliorare. Consegna il file kanban-cognome.pdf con le foto della board, il diario e la retrospettiva.', null, '2027-01-14', (select id from topics where class_id = '3g' and title = 'Progetti software e metodologie' limit 1), 'contenuti/compiti/agile-scrum-kanban.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La mia settimana in Kanban');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il piano del torneo', 'Pianifica il torneo di e-sport della scuola: almeno 10 attività con durate, dipendenze e responsabili, inizio e fine calcolati con formule, un Gantt a barre impilate con il percorso critico evidenziato e un registro di 5 rischi con punteggio, livello e contromisura. Consegna il file piano-torneo-cognome.ods (oppure .xlsx).', null, '2027-01-18', (select id from topics where class_id = '3g' and title = 'La gestione dei progetti' limit 1), 'contenuti/compiti/gestione-progetti-gantt.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il piano del torneo');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Detective del web', 'Scegli tre siti che usi e dividi i loro URL in protocollo, host, percorso, query e frammento. Con la scheda Network dei DevTools annota richieste, dati trasferiti, metodo e codice di stato, prova un indirizzo inesistente e leggi un robots.txt. Consegna il file detective-web-cognome.pdf.', null, '2027-01-21', (select id from topics where class_id = '3g' and title = 'Il World Wide Web' limit 1), 'contenuti/compiti/world-wide-web.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Detective del web');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La ricetta in HTML, a prova di validatore', 'Trasforma una ricetta di casa tua in una pagina HTML scritta a mano, con scheletro completo, un h1, almeno tre h2, paragrafi, strong, em ed entità. Validala su validator.w3.org fino a zero errori. Consegna il file ricetta-cognome.html.', null, '2027-01-25', (select id from topics where class_id = '3g' and title = 'Gli elementi base di HTML' limit 1), 'contenuti/compiti/html-elementi-base.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La ricetta in HTML, a prova di validatore');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La mia top 5', 'Costruisci una pagina con una classifica in un elenco numerato al contrario, almeno tre immagini con alt e crediti, un menu di link interni, link esterni e una tabella di confronto con caption e celle unite. Valida il codice e consegna la cartella compressa top5-cognome.zip.', null, '2027-01-27', (select id from topics where class_id = '3g' and title = 'Le pagine web con link, immagini, elenchi e tabelle' limit 1), 'contenuti/compiti/html-link-immagini-tabelle.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La mia top 5');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Restyling: stesso HTML, nuovo vestito', 'Rifai l''aspetto della tua top 5 con un solo foglio di stile esterno di almeno 10 regole, una palette con le conversioni da esadecimale a rgb() fatte a mano e nessuno stile rimasto nell''HTML. Valida il CSS e consegna restyling-cognome.zip con il sito e gli screenshot prima e dopo.', null, '2027-02-01', (select id from topics where class_id = '3g' and title = 'Lo stile della pagina web: i CSS' limit 1), 'contenuti/compiti/css-primi-stili.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Restyling: stesso HTML, nuovo vestito');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La mia passione in una pagina', 'Racconta una tua passione in una pagina web scritta a mano, con tre sezioni, due elenchi, una tabella, due immagini con licenza libera e alt, tre link esterni e un foglio di stile esterno di almeno 8 regole. Consegna la cartella compressa passione-cognome.zip con index.html, stile.css e la cartella immagini.', null, '2027-02-03', (select id from topics where class_id = '3g' and title = 'Laboratorio: la mia prima pagina web con HTML e CSS' limit 1), 'contenuti/compiti/laboratorio-prima-pagina-web.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La mia passione in una pagina');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il menu della pizzeria', 'Dai stile alla pagina già pronta di una pizzeria inventata usando classi, id, selettori discendenti, :hover e :nth-child, poi calcola la specificità di sei selettori e risolvi due casi di regole in conflitto, scrivendo le risposte in un commento. Consegna pizzeria-cognome.zip con index.html e stile.css.', null, '2027-02-05', (select id from topics where class_id = '3g' and title = 'Le classi, gli identificatori e altri selettori CSS' limit 1), 'contenuti/compiti/css-classi-id-specificita.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il menu della pizzeria');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Scatole su misura', 'Calcola a mano le dimensioni di cinque scatole CSS, poi costruisci una pagina centrata con tre carte di presentazione larghe esattamente 320 px affiancate, verificandole con lo schema del box model dei DevTools. Consegna scatole-cognome.zip con index.html, stile.css (con i calcoli in un commento) e lo screenshot boxmodel.png.', null, '2027-02-10', (select id from topics where class_id = '3g' and title = 'Il box model e i CSS layout' limit 1), 'contenuti/compiti/css-box-model-layout.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Scatole su misura');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il mio mini-sito', 'Scegli un argomento, disegna il wireframe e costruisci un sito di tre pagine con lo stesso layout (pagina centrata, menu orizzontale con voce attiva, due colonne, footer) e un solo foglio di stile, con tabella, elenco numerato, immagini con alt e link esterni. Consegna minisito-cognome.zip con il sito e wireframe.png.', null, '2027-02-12', (select id from topics where class_id = '3g' and title = 'Laboratorio: creazione di pagine web con semplice layout' limit 1), 'contenuti/compiti/laboratorio-layout-sito.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il mio mini-sito');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Ispettore del web', 'Porta il tuo sito a zero errori con i validatori W3C documentando prima e dopo, analizza un sito vero con i DevTools (selettori, box model, modalità dispositivo, file CSS) e trova almeno sei problemi in una pagina scritta da un''AI, riscrivendola corretta. Consegna il file ispettore-cognome.pdf.', null, '2027-02-16', (select id from topics where class_id = '3g' and title = 'Strumenti software per sviluppare pagine web' limit 1), 'contenuti/compiti/strumenti-sviluppo-web.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Ispettore del web');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Restauro semantico', 'Riscrivi con i tag semantici giusti la pagina a div della palestra Fit Club, con titoli in ordine, un vero pulsante e i tre tipi di testo alternativo, finché il validatore W3C non segnala errori. Poi analizza un sito vero con WAVE e riporta in un commento i risultati e due problemi spiegati. Consegna il file semantico-cognome.html.', null, '2027-02-19', (select id from topics where class_id = '3g' and title = 'HTML semantico e accessibilità' limit 1), 'contenuti/compiti/html-semantico-accessibilita.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Restauro semantico');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La vetrina del negozio', 'Costruisci la pagina delle offerte di un negozio online con almeno sei card: badge absolute sugli angoli, intestazione sticky, pulsante del carrello fixed e uno z-index che non copre nulla di importante. In un commento spiega che cosa succede togliendo position: relative alle card e top: 0 all''header. Consegna il file vetrina-cognome.html.', null, '2027-02-23', (select id from topics where class_id = '3g' and title = 'Il posizionamento degli elementi HTML' limit 1), 'contenuti/compiti/posizionamento-css.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La vetrina del negozio');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La playlist in Flexbox', 'Realizza con Flexbox la pagina di una playlist: barra in alto con titolo e menu, almeno otto card di canzoni che vanno a capo, un lettore in basso con tre pulsanti centrati e la prima canzone in evidenza con flex-grow. In un commento risolvi a mano un calcolo di flex-grow e indica il livello raggiunto in Flexbox Froggy. Consegna il file flexbox-cognome.html.', null, '2027-02-26', (select id from topics where class_id = '3g' and title = 'Il layout CSS Flexbox' limit 1), 'contenuti/compiti/css-flexbox.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La playlist in Flexbox');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'L''orario della 3E in CSS Grid', 'Ricostruisci il tuo vero orario scolastico come pagina web con CSS Grid, senza tabelle: giorni in colonna, ore in riga, ogni ora doppia come un solo elemento su due righe e la pagina impaginata con grid-template-areas. In un commento calcola la larghezza di una colonna e indica il livello raggiunto in Grid Garden. Consegna il file orario-cognome.html.', null, '2027-03-02', (select id from topics where class_id = '3g' and title = 'Il layout CSS Grid' limit 1), 'contenuti/compiti/css-grid.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'L''orario della 3E in CSS Grid');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La mia pagina in tre misure', 'Riprendi la tua pagina personale dell''Unità 4 e riscrivi il CSS in modo mobile first: meta viewport, almeno due media query con min-width in ordine crescente, immagini fluide, tema scuro e un commento che motiva i breakpoint. Salva gli screenshot a 360, 768 e 1280 px. Consegna il file responsive-cognome.zip con HTML, CSS e i tre PNG.', null, '2027-03-04', (select id from topics where class_id = '3g' and title = 'La progettazione di un sito web responsive' limit 1), 'contenuti/compiti/responsive-mobile-first.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La mia pagina in tre misure');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'CineTerza, la seconda pagina', 'Completa la home di CineTerza e aggiungi la pagina rassegna.html con quattro schede impaginate con grid-template-areas e due media query mobile first, una scheda in evidenza su due righe e Flexbox dentro ogni scheda. Collauda con Tab e validatori e salva due screenshot. Consegna il file cineterza-cognome.zip.', null, '2027-03-09', (select id from topics where class_id = '3g' and title = 'Laboratorio: realizziamo un sito responsive con Flexbox e Grid Layout' limit 1), 'contenuti/compiti/sito-responsive-flexbox-grid.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'CineTerza, la seconda pagina');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La pagina del mio podcast', 'Registra una puntata di 60-90 secondi su un luogo che ami e pubblicala in una pagina con il lettore audio, la trascrizione completa, la mappa di OpenStreetMap incorporata con title e lazy loading e il calcolo del peso del file MP3. Consegna il file podcast-cognome.zip con podcast.html, stile.css e puntata.mp3.', null, '2027-03-11', (select id from topics where class_id = '3g' and title = 'Contenuti multimediali e incorporati (embedded)' limit 1), 'contenuti/compiti/multimedia-embedded.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La pagina del mio podcast');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La vetrina senza breakpoint', 'Costruisci una vetrina delle tue cose preferite con titolo in clamp(), tag che vanno a capo con flex-wrap e una galleria con auto-fit e minmax, senza nessuna media query sulla larghezza. In un commento calcola le colonne a tre larghezze e verifica con DevTools. Consegna il file vetrina-cognome.html.', null, '2027-03-15', (select id from topics where class_id = '3g' and title = 'Sito web responsive senza media query' limit 1), 'contenuti/compiti/responsive-senza-media-query.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La vetrina senza breakpoint');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il diario di bordo del mio computer', 'Con Gestione attività rileva in tre momenti diversi utilizzo della CPU, processi, thread e memoria in uso. In Calc calcola la percentuale di RAM usata e i processi per core, crea un grafico e spiega i risultati con i termini della lezione. Consegna il file diario-so-cognome.ods.', null, '2027-03-18', (select id from topics where class_id = '3g' and title = 'Il ruolo del sistema operativo' limit 1), 'contenuti/compiti/ruolo-sistema-operativo.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il diario di bordo del mio computer');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La mia guida tascabile alla shell', 'Prepara una guida a 8 comandi nelle versioni per cmd e per Linux, provati davvero nel Prompt dei comandi e su JSLinux, con esempi, screenshot e un esempio di pipe per ciascun sistema. Spiega per 3 comandi che cosa fa la shell e che cosa chiede al kernel. Consegna il file shell-cognome.pdf.', null, '2027-03-22', (select id from topics where class_id = '3g' and title = 'Due componenti fondamentali: il kernel e la shell' limit 1), 'contenuti/compiti/kernel-e-shell.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La mia guida tascabile alla shell');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Rapporto d''incidente: il giorno delle schermate blu', 'Scrivi il rapporto d''incidente del guasto CrowdStrike del 19 luglio 2024 usando almeno 2 fonti affidabili: riassunto, conseguenze, causa tecnica, perché un errore in kernel mode ferma tutto e lezioni imparate, con uno schema degli anelli disegnato da te. Consegna il file incidente-cognome.pdf.', null, '2027-03-24', (select id from topics where class_id = '3g' and title = 'Il modello a ring con user mode e kernel mode' limit 1), 'contenuti/compiti/user-mode-kernel-mode.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Rapporto d''incidente: il giorno delle schermate blu');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Caccia ai sistemi operativi di casa', 'Trova almeno 10 oggetti con un sistema operativo, classificali per tipologia motivando la scelta e i vincoli real time, e riassumili con CONTA.SE e un grafico. In un secondo foglio calcola l''utilizzo della CPU di un job e l''attesa massima in un sistema time sharing. Consegna il file caccia-so-cognome.ods.', null, '2027-04-02', (select id from topics where class_id = '3g' and title = 'Tipologie di sistemi operativi' limit 1), 'contenuti/compiti/tipologie-sistemi-operativi.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Caccia ai sistemi operativi di casa');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La carta d''identità di un sistema operativo', 'Scegli un sistema operativo meno famoso (per esempio FreeBSD, Raspberry Pi OS, SteamOS, KaiOS, FreeRTOS) e prepara un poster di una pagina con anno, autori, famiglia, kernel, licenza, tipologia, uso attuale, una curiosità, una linea del tempo e le fonti. Consegna il file so-cognome.pdf oppure so-cognome.png.', null, '2027-04-06', (select id from topics where class_id = '3g' and title = 'I sistemi operativi in commercio' limit 1), 'contenuti/compiti/sistemi-operativi-commercio.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La carta d''identità di un sistema operativo');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Check-up del mio PC', 'Misura il tuo PC a riposo e sotto sforzo con Gestione attività, confronta i valori in una tabella e trova con Monitoraggio risorse i processi che usano più CPU, RAM e rete. Individua il collo di bottiglia, dai un consiglio e risolvi l''esercizio su throughput e utilizzo. Consegna il file checkup-pc-cognome.pdf.', null, '2027-04-08', (select id from topics where class_id = '3g' and title = 'Le prestazioni del sistema operativo' limit 1), 'contenuti/compiti/prestazioni-sistema-operativo.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Check-up del mio PC');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il diario di un processo', 'Salva l''elenco dei processi con tasklist, spiega 3 processi di sistema che non conosci e annota thread e tempo CPU. Poi racconta in almeno 8 passaggi la vita del processo di un''app che usi, stato per stato, con il diagramma dei cinque stati e le frecce numerate. Consegna il file diario-processo-cognome.pdf.', null, '2027-04-13', (select id from topics where class_id = '3g' and title = 'La gestione della CPU: i processi' limit 1), 'contenuti/compiti/processi-stati-pcb.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il diario di un processo');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Lo scheduler sei tu', 'Simula in Calc FCFS, SJF, priorità e Round Robin con quanto 2 su cinque processi, con un diagramma di Gantt a celle colorate e i controlli per ogni algoritmo. Calcola tempi di completamento e di attesa e le medie, confrontali con un grafico e scegli l''algoritmo per un telefono motivando. Consegna il file scheduling-cognome.ods.', null, '2027-04-15', (select id from topics where class_id = '3g' and title = 'Gli algoritmi di scheduling dei processi' limit 1), 'contenuti/compiti/scheduling-processi.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Lo scheduler sei tu');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Caccia agli interrupt', 'Trova 6 situazioni della tua giornata, 3 di interrupt e 3 di polling, classificale e proponi come trasformare il polling in interrupt. Osserva gli IRQ del PC in Gestione dispositivi o in JSLinux, collega una situazione ai passi della gestione di un interrupt e risolvi tre esercizi di calcolo. Consegna il file interrupt-cognome.pdf.', null, '2027-04-19', (select id from topics where class_id = '3g' and title = 'La gestione degli interrupt' limit 1), 'contenuti/compiti/gestione-interrupt.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Caccia agli interrupt');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il mio PC sotto la lente', 'Fai la radiografia della memoria di un PC con il Task Manager e il comando systeminfo, costruisci in Calc una MMU con base e limite per tre processi e risolvi alcuni conti su potenze di 2 e tempi di accesso. Consegna il file memoria-cognome.ods.', null, '2027-04-22', (select id from topics where class_id = '3g' and title = 'La gestione della memoria fisica e virtuale' limit 1), 'contenuti/compiti/memoria-fisica-virtuale.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il mio PC sotto la lente');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il torneo dei buchi', 'Applica first fit, best fit e worst fit a cinque richieste di memoria, aggiornando la lista dei buchi a ogni passo, e scopri quale algoritmo sistema tutti i processi. Calcola anche la frammentazione interna di un caso con partizioni fisse. Consegna il file partizioni-cognome.ods (oppure un PDF con le foto dei fogli).', null, '2027-04-26', (select id from topics where class_id = '3g' and title = 'L''allocazione contigua a partizioni' limit 1), 'contenuti/compiti/allocazione-partizioni.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il torneo dei buchi');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Detective degli indirizzi', 'Traduci a mano indirizzi logici in fisici con pagine da 1024 byte e, senza divisioni, con pagine da 4 KB in esadecimale; verifica con Calc, Java o la console del browser. Calcola pagine, spreco e dimensione della tabella in due casi. Consegna il file paginazione-cognome.ods (oppure un PDF con le foto dei fogli).', null, '2027-04-28', (select id from topics where class_id = '3g' and title = 'L''allocazione non contigua a paginazione statica' limit 1), 'contenuti/compiti/paginazione-statica.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Detective degli indirizzi');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Caccia al page fault', 'Compila le tabelle FIFO, LRU e OPT per una sequenza di 12 riferimenti con 3 e con 4 frame e conta i page fault in Calc. Confronta i risultati, verifica FIFO con il programma Java della lezione e spiega sintomi e rimedi del thrashing. Consegna il file page-fault-cognome.ods.', null, '2027-05-03', (select id from topics where class_id = '3g' and title = 'La memoria virtuale a paginazione dinamica' limit 1), 'contenuti/compiti/paginazione-dinamica.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Caccia al page fault');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La MMU a segmenti', 'Traduci sei accessi con una tabella dei segmenti che ha anche i permessi, riconoscendo gli errori; disegna la mappa della RAM, trova i buchi e scegli dove mettere un nuovo segmento con first, best e worst fit. Completa un confronto tra paginazione e segmentazione e un piccolo programma Java che controlla il limite. Consegna il file segmenti-cognome.ods.', null, '2027-05-05', (select id from topics where class_id = '3g' and title = 'La memoria virtuale a segmentazione' limit 1), 'contenuti/compiti/segmentazione-memoria.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La MMU a segmenti');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il guardiano dei file', 'Organizza le cartelle del server del giornalino della scuola, scrivi percorsi assoluti e relativi e decidi i permessi di 4 file in lettere, in ottale e con il comando chmod. Prova tutto su JSLinux con uno screenshot di ls -l e scegli il file system giusto per 4 situazioni. Consegna il file guardiano-cognome.pdf.', null, '2027-05-07', (select id from topics where class_id = '3g' and title = 'La gestione delle informazioni: il file system' limit 1), 'contenuti/compiti/file-system-permessi.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il guardiano dei file');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Detective del disco', 'Ricostruisci in Calc i file di una chiavetta rovinata seguendo le catene della FAT con CERCA.VERT, calcola lo spazio sprecato da 6 file veri con blocchi da 4 KB e svolgi il calcolo dei puntatori di un i-node. Consegna il file detective-disco-cognome.ods.', null, '2027-05-12', (select id from topics where class_id = '3g' and title = 'L''allocazione dello spazio su disco' limit 1), 'contenuti/compiti/allocazione-spazio-disco.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Detective del disco');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Censimento delle periferiche', 'Classifica 8 periferiche del tuo PC o del telefono (tipo, blocchi o caratteri, driver o firmware), annota la carta d''identità di 2 driver, calcola tempi di copia e numero di interrupt con il DMA e distingui buffering e spooling in 3 casi. Consegna il file periferiche-cognome.pdf.', null, '2027-05-14', (select id from topics where class_id = '3g' and title = 'La gestione delle periferiche' limit 1), 'contenuti/compiti/gestione-periferiche.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Censimento delle periferiche');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il mio piano di sicurezza', 'Controlla 5 tuoi account (senza scrivere dati personali) indicando password riusate e secondo fattore, progetta il tuo backup 3-2-1 e verificane una copia con l''impronta SHA-256, poi analizza 3 messaggi e riconosci il phishing. Consegna il file sicurezza-cognome.pdf.', null, '2027-05-18', (select id from topics where class_id = '3g' and title = 'La protezione e la sicurezza dei dati' limit 1), 'contenuti/compiti/protezione-sicurezza-dati.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il mio piano di sicurezza');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Lavoro di gruppo: DomoDash, il cruscotto della casa intelligente', 'La squadra progetta e costruisce il cruscotto web di una casa domotica simulata: Kanban, wireframe, card in HTML e CSS generate dal file dati.js con lo script di partenza, test di accessibilità e presentazione di 5 minuti. Il coordinatore carica un solo file domodash-squadraN.zip con il sito, Kanban, wireframe, test e le slide in PDF.', null, '2027-05-21', (select id from topics where class_id = '3g' and title = 'Progetto: la casa intelligente' limit 1), 'contenuti/compiti/progetto-casa-intelligente.pdf', true where not exists (select 1 from assignments where class_id = '3g' and title = 'Lavoro di gruppo: DomoDash, il cruscotto della casa intelligente');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Lavoro di gruppo: il nostro Comune a raggi X', 'La squadra costruisce un sito di 5 pagine, responsive e accessibile, su rifiuti ed energia del proprio Comune usando solo dati pubblici verificati e citati. Il coordinatore carica un solo file comune-squadraN.zip con il sito, il foglio dei dati, il wireframe, i test e le slide della presentazione in PDF.', null, '2027-05-25', (select id from topics where class_id = '3g' and title = 'Progetto: un sito per l''ambiente' limit 1), 'contenuti/compiti/progetto-sito-ambiente.pdf', true where not exists (select 1 from assignments where class_id = '3g' and title = 'Lavoro di gruppo: il nostro Comune a raggi X');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il censimento elettronico di casa', 'Fai il censimento di almeno 15 apparecchi elettronici di casa, compresi quelli che non si usano più, e per ognuno indica gruppo RAEE e destinazione corretta, con le formule CONTA.SE di Calc. Scrivi il piano di seconda vita di un apparecchio inutilizzato. Consegna il file raee-casa-cognome.ods.', null, '2027-05-27', (select id from topics where class_id = '3g' and title = 'Smaltimento dei rifiuti elettronici' limit 1), 'contenuti/compiti/raee-rifiuti-elettronici.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il censimento elettronico di casa');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'La pagina con i crediti giusti', 'Costruisci una pagina web su un tema a scelta con tre immagini davvero utilizzabili, una tua immagine e un brano musicale libero, ognuno con crediti completi in HTML, una tabella riassuntiva e la licenza Creative Commons dei tuoi contenuti nel footer. Consegna il file crediti-cognome.zip.', null, '2027-06-01', (select id from topics where class_id = '3g' and title = 'Diritto d''autore e uso del materiale in rete' limit 1), 'contenuti/compiti/diritto-autore-in-rete.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'La pagina con i crediti giusti');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, group_work) select '3g', 'Il DVR della mia postazione di studio', 'Valuta almeno 8 rischi della postazione dove studi con la matrice probabilità per danno e le formule SE di Calc, calcola la potenza degli apparecchi collegati alla ciabatta e confrontala con il limite, poi compila con un familiare le informazioni di emergenza di casa. Consegna il file dvr-casa-cognome.ods.', null, '2027-06-04', (select id from topics where class_id = '3g' and title = 'Sicurezza sul luogo di lavoro' limit 1), 'contenuti/compiti/sicurezza-lavoro-laboratorio.pdf', false where not exists (select 1 from assignments where class_id = '3g' and title = 'Il DVR della mia postazione di studio');
