insert into tests (class_id, position, title, description, test_date, practice_url) select '3g', 30, 'Verifica Unità 3: sviluppare software', 'Ingegneria del software e qualità, manutenzione, requisiti funzionali e non funzionali, modelli del ciclo di vita, casi di test e valori al limite in Java, Manifesto agile, Scrum e Kanban, WBS, diagramma di Gantt, percorso critico, legge di Brooks e rischi.', '2027-01-22', 'contenuti/verifiche/3e-u3-simulazione.pdf' where not exists (select 1 from tests where class_id = '3g' and title = 'Verifica Unità 3: sviluppare software');
