insert into tests (class_id, position, title, description, test_date, practice_url) select '3g', 40, 'Verifica Unità 4: il WWW e le pagine web', 'Web e Internet, DNS, URL e codici di stato HTTP, struttura e annidamento dell''HTML, link e percorsi relativi, immagini, tabelle con caption e colspan, regole CSS, classi, id, pseudo-classi e specificità, box model e display, strumenti di sviluppo, validatori e uso critico dell''AI.', '2027-02-22', 'contenuti/verifiche/3e-u4-simulazione.pdf' where not exists (select 1 from tests where class_id = '3g' and title = 'Verifica Unità 4: il WWW e le pagine web');
