insert into tests (class_id, position, title, description, test_date, practice_url) select '3g', 50, 'Verifica Unità 5: siti web responsive e accessibili', 'HTML semantico e testo alternativo, posizionamento e z-index, Flexbox e Grid con i calcoli di flex-grow e fr, meta viewport e pixel CSS, mobile first e ordine delle media query, una pagina con grid-template-areas, video con sottotitoli WebVTT, privacy degli embed, clamp() e auto-fit.', '2027-03-19', 'contenuti/verifiche/3e-u5-simulazione.pdf' where not exists (select 1 from tests where class_id = '3g' and title = 'Verifica Unità 5: siti web responsive e accessibili');
