insert into tests (class_id, position, title, description, test_date, practice_url) select '3g', 60, 'Verifica Unità 6: introduzione ai sistemi operativi', 'Ruolo del sistema operativo, kernel e shell, user mode e kernel mode, tipologie e sistemi in commercio, prestazioni, processi e stati, scheduling FCFS, SJF e Round Robin con diagrammi di Gantt, interrupt e polling.', '2027-04-23', 'contenuti/verifiche/3e-u6-simulazione.pdf' where not exists (select 1 from tests where class_id = '3g' and title = 'Verifica Unità 6: introduzione ai sistemi operativi');
