insert into tests (class_id, position, title, description, test_date, practice_url) select '3g', 70, 'Verifica Unità 7: il sistema operativo come gestore di risorse', 'Gerarchia delle memorie e indirizzi, partizioni con first, best e worst fit, traduzione degli indirizzi con paginazione e segmentazione, sostituzione delle pagine FIFO e LRU, file system e permessi, FAT e i-node, periferiche, DMA e spooling, protezione, backup e malware.', '2027-05-24', 'contenuti/verifiche/3e-u7-simulazione.pdf' where not exists (select 1 from tests where class_id = '3g' and title = 'Verifica Unità 7: il sistema operativo come gestore di risorse');
